                let base = pds_of(&db, &team_id).await;
                let id = id_of(&create(&s, &cookie, input(&set, "video", Some(&past()))).await);
                set_media(&db, &base, &id, &["/clip.mp4"]).await;
                publish::tick(&state).await.unwrap();
