            fn thread_input(set: &str, body: &str, parts: &[&str]) -> Value {
                let mut v = input(set, body, Some(&past()));
                v["thread"] = parts.iter().map(|p| json!({"body": p})).collect();
                v
            }

            fn rkey(uri: &str) -> String {
                uri.rsplit('/').next().unwrap().to_owned()
            }

            #[tokio::test]
            #[serial]
            async fn threads_are_validated_and_round_trip() {
                let (s, db, _) = on_mock().await;
                let (cookie, team_id, _) = owner_with_account(&s, &db).await;
                let set = default_set(&db, &team_id).await.to_string();
                let long = "a".repeat(301);
                let mut five_images = thread_input(&set, "root", &["ok", "ok"]);
                five_images["thread"][1]["media"] = json!(vec!["https://a.example/1.png"; 5]);
                let many: Vec<&str> = vec!["x"; 26];
                for (body, want) in [
                    (
                        thread_input(&set, "root", &many),
                        json!({"error": "too_many_parts", "platform": "bluesky", "field": "thread",
                            "limit": 25, "actual": 26,
                            "detail": "The thread has 26 follow-up posts; the limit is 25."}),
                    ),
                    (
                        thread_input(&set, "root", &["ok", &long]),
                        json!({"error": "too_long", "platform": "bluesky", "field": "body",
                            "part": 2, "limit": 300, "actual": 301,
                            "detail": "The text is 301 graphemes; the limit is 300."}),
                    ),
                    (
                        five_images,
                        json!({"error": "too_many_images", "platform": "bluesky", "field": "media",
                            "part": 2, "limit": 4, "actual": 5,
                            "detail": "The post has 5 media items; the limit is 4."}),
                    ),
                    (
                        thread_input(&set, "root", &[" "]),
                        json!({"error": "empty_post", "platform": "bluesky", "field": "body",
                            "part": 1}),
                    ),
                ] {
                    let res = create(&s, &cookie, body).await;
                    assert_eq!(res.status_code(), 422);
                    res.assert_json(&want);
                }
                let mut body = input(&set, "root", None);
                body["thread"] = json!([{"body": "two", "media": ["https://a.example/i.png"]},
                    {"body": "three"}]);
                let res = create(&s, &cookie, body).await;
                assert_eq!(res.status_code(), 201);
                let p = res.json::<Value>();
                assert_eq!(
                    p["thread"],
                    json!([{"body": "two", "media": ["https://a.example/i.png"]},
                        {"body": "three", "media": []}])
                );
                let id = id_of_post(&p);
                assert_eq!(get_post(&s, &cookie, &id).await["thread"], p["thread"]);
                let path = format!("/v1/posts/{id}");
                let res = req(&s, Method::PUT, &path, &cookie)
                    .json(&thread_input(&set, "root", &["only"]))
                    .await;
                res.assert_status_ok();
                assert_eq!(
                    res.json::<Value>()["thread"],
                    json!([{"body": "only", "media": []}])
                );
                // A full thread fits the body limit.
                let full = "🦀".repeat(300);
                let parts: Vec<&str> = vec![&full; 25];
                let res = req(&s, Method::PUT, &path, &cookie)
                    .json(&thread_input(&set, "root", &parts))
                    .await;
                res.assert_status_ok();
                let res = req(&s, Method::PUT, &path, &cookie)
                    .json(&input(&set, "no thread", None))
                    .await;
                assert_eq!(res.json::<Value>()["thread"], json!([]));
            }

            fn id_of_post(p: &Value) -> String {
                p["id"].as_str().unwrap().to_owned()
            }

            #[tokio::test]
            #[serial]
            async fn a_thread_goes_out_as_replies_and_comes_down_children_first() {
                let (s, db, state) = on_mock().await;
                let (cookie, team_id, _) = owner_with_account(&s, &db).await;
                let set = default_set(&db, &team_id).await.to_string();
                let id =
                    id_of(&create(&s, &cookie, thread_input(&set, "one", &["two", "three"])).await);
                let before = RECORDS.lock().unwrap().len();
                publish::tick(&state).await.unwrap();
                let p = get_post(&s, &cookie, &id).await;
                assert_eq!(p["status"], "published", "{p}");
                let t = &p["targets"][0];
                assert_eq!(t["status"], "published");
                let root = t["remote_id"].as_str().unwrap().to_owned();
                let parts = t["parts"].as_array().unwrap();
                assert_eq!(parts.len(), 2);
                assert!(parts[1]["remote_url"]
                    .as_str()
                    .unwrap()
                    .starts_with("https://bsky.app/profile/"));
                let records: Vec<Value> = RECORDS.lock().unwrap()[before..].to_vec();
                let texts: Vec<&str> = records
                    .iter()
                    .map(|r| r["record"]["text"].as_str().unwrap())
                    .collect();
                assert_eq!(texts, ["one", "two", "three"]);
                assert!(records[0]["record"].get("reply").is_none());
                let reply = |i: usize| records[i]["record"]["reply"].clone();
                assert_eq!(reply(1)["root"], json!({"uri": root, "cid": "bafycid"}));
                assert_eq!(reply(1)["parent"]["uri"], root.as_str());
                assert_eq!(reply(2)["root"]["uri"], root.as_str());
                assert_eq!(reply(2)["parent"]["uri"], parts[0]["remote_id"]);
                let row = post_targets::Entity::find()
                    .filter(post_targets::Column::PostId.eq(id.parse::<uuid::Uuid>().unwrap()))
                    .one(&db)
                    .await
                    .unwrap()
                    .unwrap();
                assert_eq!(row.remote_cid.as_deref(), Some("bafycid"));
                assert_eq!(row.parts[0]["cid"], "bafycid");

                let res = req(&s, Method::DELETE, &format!("/v1/posts/{id}"), &cookie).await;
                res.assert_status_ok();
                let body = res.json::<Value>();
                assert_eq!(body["status"], "deleted");
                assert_eq!(body["targets"][0]["parts"], json!([]));
                let deleted = DELETED.lock().unwrap().clone();
                let n = deleted.len();
                assert_eq!(
                    deleted[n - 3..],
                    [
                        rkey(parts[1]["remote_id"].as_str().unwrap()),
                        rkey(parts[0]["remote_id"].as_str().unwrap()),
                        rkey(&root),
                    ]
                );
            }

            #[tokio::test]
            #[serial]
            async fn an_expired_cached_session_is_opened_again() {
                let (s, db, state) = on_mock().await;
                let (cookie, team_id, _) = owner_with_account(&s, &db).await;
                let set = default_set(&db, &team_id).await.to_string();
                let body = thread_input(&set, "one", &["two"]);
                let first = id_of(&create(&s, &cookie, body).await);
                publish::tick(&state).await.unwrap();
                assert_eq!(get_post(&s, &cookie, &first).await["status"], "published");
                // The cached session now answers 400 ExpiredToken once, mid-thread.
                let id = id_of(&create(&s, &cookie, thread_input(&set, "a", &["b"])).await);
                let before = RECORDS.lock().unwrap().len();
                EXPIRE_NEXT.store(true, std::sync::atomic::Ordering::SeqCst);
                publish::tick(&state).await.unwrap();
                let p = get_post(&s, &cookie, &id).await;
                assert_eq!(p["status"], "published", "{p}");
                assert_eq!(p["targets"][0]["parts"].as_array().unwrap().len(), 1);
                assert_eq!(RECORDS.lock().unwrap().len(), before + 2, "each sent once");
                assert!(!EXPIRE_NEXT.load(std::sync::atomic::Ordering::SeqCst));
            }

            #[tokio::test]
            #[serial]
            async fn a_failed_part_keeps_the_parts_before_it() {
                let (s, db, state) = on_mock().await;
                let (cookie, team_id, _) = owner_with_account(&s, &db).await;
                let set = default_set(&db, &team_id).await.to_string();
                let body = thread_input(&set, "one", &["two", "REJECT three", "four"]);
                let id = id_of(&create(&s, &cookie, body).await);
                let before = RECORDS.lock().unwrap().len();
                publish::tick(&state).await.unwrap();
                assert_eq!(RECORDS.lock().unwrap().len(), before + 2, "four never went");
                let p = get_post(&s, &cookie, &id).await;
                // The root is up, so the post is published and can come down.
                assert_eq!(p["status"], "published", "{p}");
                let t = &p["targets"][0];
                assert_eq!(t["status"], "failed");
                assert_eq!(
                    t["error"],
                    "Thread post 2 of 3: Bluesky refused it (InvalidRequest). The posts before \
                     it are up."
                );
                assert!(p["error"].as_str().unwrap().contains("Thread post 2 of 3"));
                assert_eq!(t["parts"].as_array().unwrap().len(), 1);
                assert!(t["remote_url"].is_string());

                // Never sent again: the target stays failed with its saved part.
                publish::publish_post(&state, id.parse().unwrap())
                    .await
                    .unwrap();
                publish::recover_stuck(&db).await.unwrap();
                assert_eq!(RECORDS.lock().unwrap().len(), before + 2);

                let res = req(&s, Method::DELETE, &format!("/v1/posts/{id}"), &cookie).await;
                res.assert_status_ok();
                let body = res.json::<Value>();
                assert_eq!(body["status"], "deleted");
                assert_eq!(body["targets"][0]["status"], "deleted");
            }

            fn retry_url(id: &str) -> String {
                format!("/v1/posts/{id}/retry")
            }

            async fn set_body(db: &DatabaseConnection, id: &str, body: &str, thread: Value) {
                let row = posts::ActiveModel {
                    id: Set(id.parse().unwrap()),
                    body: Set(body.into()),
                    thread: Set(thread),
                    ..Default::default()
                };
                posts::Entity::update(row).exec(db).await.unwrap();
            }

            #[tokio::test]
            #[serial]
            async fn a_retry_continues_a_thread_after_its_saved_parts() {
                let (s, db, state) = on_mock().await;
                let (cookie, team_id, _) = owner_with_account(&s, &db).await;
                let set = default_set(&db, &team_id).await.to_string();
                let body = thread_input(&set, "one", &["two", "REJECT three", "four"]);
                let id = id_of(&create(&s, &cookie, body).await);
                publish::tick(&state).await.unwrap();
                let p = get_post(&s, &cookie, &id).await;
                let t = &p["targets"][0];
                assert_eq!(
                    (p["status"].as_str(), t["status"].as_str()),
                    (Some("published"), Some("failed"))
                );
                let root = t["remote_id"].as_str().unwrap().to_owned();
                let first_part = t["parts"][0]["remote_id"].clone();

                // Nothing is sent again while it still fails the same way: it fails at part 3.
                set_body(
                    &db,
                    &id,
                    "one",
                    json!([{"body": "two"}, {"body": "three"}, {"body": "four"}]),
                )
                .await;
                let before = RECORDS.lock().unwrap().len();
                let res = req(&s, Method::POST, &retry_url(&id), &cookie).await;
                assert_eq!(res.status_code(), 202, "{}", res.text());
                assert_eq!(res.json::<Value>()["status"], "queued");
                let p = settled(&s, &cookie, &id).await;
                assert_eq!(p["status"], "published", "{p}");
                assert_eq!(p["error"], Value::Null);
                let t = &p["targets"][0];
                assert_eq!(t["status"], "published");
                assert_eq!(t["error"], Value::Null);
                assert_eq!(t["remote_id"], root.as_str());
                assert_eq!(t["parts"].as_array().unwrap().len(), 3);
                // The root and part one are not posted again: three and four follow part one.
                let records: Vec<Value> = RECORDS.lock().unwrap()[before..].to_vec();
                let texts: Vec<&str> = records
                    .iter()
                    .map(|r| r["record"]["text"].as_str().unwrap())
                    .collect();
                assert_eq!(texts, ["three", "four"]);
                let reply = |i: usize| records[i]["record"]["reply"].clone();
                assert_eq!(reply(0)["root"]["uri"], root.as_str());
                assert_eq!(reply(0)["parent"]["uri"], first_part);
                assert_eq!(reply(1)["parent"]["uri"], t["parts"][1]["remote_id"]);

                // Published now: nothing to retry.
                let res = req(&s, Method::POST, &retry_url(&id), &cookie).await;
                assert_eq!(res.status_code(), 409);
                res.assert_json(&json!({"error": "nothing_to_retry"}));
                assert_eq!(RECORDS.lock().unwrap().len(), before + 2);
            }

            #[tokio::test]
            #[serial]
            async fn a_retry_sends_failed_targets_only_and_waits_for_a_busy_post() {
                let (s, db, state) = on_mock().await;
                let (cookie, team_id, _) = owner_with_account(&s, &db).await;
                let set = default_set(&db, &team_id).await.to_string();
                let id = id_of(&create(&s, &cookie, input(&set, "REJECT me", Some(&past()))).await);
                publish::tick(&state).await.unwrap();
                let p = get_post(&s, &cookie, &id).await;
                assert_eq!(p["status"], "failed", "{p}");
                // A second account's target is already up (its account is gone), never sent again.
                let other = uuid::Uuid::now_v7();
                let up = post_targets::ActiveModel {
                    id: Set(other),
                    post_id: Set(id.parse().unwrap()),
                    social_account_id: Set(None),
                    status: Set("published".into()),
                    remote_id: Set(Some("at://did:plc:gone/app.bsky.feed.post/up".into())),
                    ..Default::default()
                };
                post_targets::Entity::insert(up)
                    .exec_without_returning(&db)
                    .await
                    .unwrap();
                set_body(&db, &id, "fine", json!([])).await;

                // A target mid-publish holds the whole retry back.
                let mid = |status: &'static str| {
                    let db = &db;
                    async move {
                        let row = post_targets::ActiveModel {
                            id: Set(other),
                            status: Set(status.into()),
                            ..Default::default()
                        };
                        post_targets::Entity::update(row).exec(db).await.unwrap();
                    }
                };
                mid("publishing").await;
                let before = RECORDS.lock().unwrap().len();
                let res = req(&s, Method::POST, &retry_url(&id), &cookie).await;
                assert_eq!(res.status_code(), 409);
                res.assert_json(&json!({"error": "publish_in_progress"}));
                mid("published").await;

                let res = req(&s, Method::POST, &retry_url(&id), &cookie).await;
                assert_eq!(res.status_code(), 202, "{}", res.text());
                let p = settled(&s, &cookie, &id).await;
                assert_eq!(p["status"], "published", "{p}");
                assert_eq!(
                    RECORDS.lock().unwrap().len(),
                    before + 1,
                    "one send, not two"
                );
                let targets = p["targets"].as_array().unwrap();
                assert_eq!(targets.len(), 2);
                assert!(targets.iter().all(|t| t["status"] == "published"));
                let up = targets
                    .iter()
                    .find(|t| t["id"] == other.to_string())
                    .unwrap();
                assert_eq!(up["remote_id"], "at://did:plc:gone/app.bsky.feed.post/up");

                // Unknown, drafts and scheduled posts have nothing to retry.
                let res = req(
                    &s,
                    Method::POST,
                    &retry_url(&uuid::Uuid::now_v7().to_string()),
                    &cookie,
                )
                .await;
                assert_eq!(res.status_code(), 404);
                let draft = id_of(&create(&s, &cookie, input(&set, "d", None)).await);
                let res = req(&s, Method::POST, &retry_url(&draft), &cookie).await;
                res.assert_json(&json!({"error": "nothing_to_retry"}));
            }

            #[tokio::test]
            #[serial]
            async fn a_group_takes_down_per_platform_and_never_repeats_a_delete_that_worked() {
                let (s, db, state) = on_mock().await;
                let (cookie, team_id, _) = owner_with_account(&s, &db).await;
                let set = default_set(&db, &team_id).await.to_string();
                let fine = id_of(&create(&s, &cookie, input(&set, "fine", Some(&past()))).await);
                let sticky =
                    id_of(&create(&s, &cookie, input(&set, "STICKY", Some(&past()))).await);
                publish::tick(&state).await.unwrap();
                let draft = id_of(&create(&s, &cookie, input(&set, "draft", None)).await);
                // The mock has one platform, so tie three posts into one group by hand.
                let gid = uuid::Uuid::now_v7();
                let ids: Vec<uuid::Uuid> = [&fine, &sticky, &draft]
                    .iter()
                    .map(|i| i.parse().unwrap())
                    .collect();
                posts::Entity::update_many()
                    .col_expr(posts::Column::GroupId, gid.into())
                    .filter(posts::Column::Id.is_in(ids))
                    .exec(&db)
                    .await
                    .unwrap();
                let url = format!("/v1/post-groups/{gid}/takedown");
                let state_of = |body: &Value, id: &str| {
                    let r = body["results"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .find(|r| r["post_id"] == id)
                        .unwrap()
                        .clone();
                    (
                        r["state"].as_str().unwrap().to_owned(),
                        r["message"].clone(),
                    )
                };

                let before = DELETED.lock().unwrap().len();
                let res = req(&s, Method::POST, &url, &cookie).await;
                assert_eq!(res.status_code(), 200, "{}", res.text());
                let body = res.json::<Value>();
                assert_eq!(body["group_id"], gid.to_string());
                assert_eq!(state_of(&body, &fine).0, "taken_down");
                let (st, msg) = state_of(&body, &sticky);
                assert_eq!(st, "failed");
                assert!(msg.as_str().unwrap().contains("Bluesky app"), "{msg}");
                assert_eq!(state_of(&body, &draft).0, "not_published");
                assert_eq!(DELETED.lock().unwrap().len(), before + 1);
                assert_eq!(get_post(&s, &cookie, &fine).await["status"], "deleted");
                assert_eq!(get_post(&s, &cookie, &sticky).await["status"], "published");
                assert_eq!(get_post(&s, &cookie, &draft).await["status"], "draft");

                // Again: the post that came down is not called, the stuck one is tried once more.
                let res = req(&s, Method::POST, &url, &cookie).await;
                assert_eq!(res.status_code(), 200, "{}", res.text());
                let body = res.json::<Value>();
                assert_eq!(state_of(&body, &fine).0, "already_gone");
                assert_eq!(state_of(&body, &sticky).0, "failed");
                assert_eq!(
                    DELETED.lock().unwrap().len(),
                    before + 1,
                    "no second delete"
                );

                let nobody = uuid::Uuid::now_v7();
                let res = req(
                    &s,
                    Method::POST,
                    &format!("/v1/post-groups/{nobody}/takedown"),
                    &cookie,
                )
                .await;
                assert_eq!(res.status_code(), 404);

                // Another team's member gets 404 and nothing is called.
                let (_, stranger, _) = user(&s, &db).await;
                let res = req(&s, Method::POST, &url, &stranger).await;
                assert_eq!(res.status_code(), 404);
                assert_eq!(DELETED.lock().unwrap().len(), before + 1);
            }

            #[tokio::test]
            #[serial]
            async fn a_retry_leaves_failures_that_may_have_posted_to_the_caller() {
                let (s, db, state) = on_mock().await;
                let (cookie, team_id, _) = owner_with_account(&s, &db).await;
                let set = default_set(&db, &team_id).await.to_string();
                let made = req(&s, Method::POST, "/v1/post-groups", &cookie)
                    .json(&json!({"social_set_id": set, "body": "REJECT me",
                        "platforms": ["bluesky"], "scheduled_at": past()}))
                    .await
                    .json::<Value>();
                let gid = made["group_id"].as_str().unwrap().to_owned();
                let id = made["posts"][0]["id"].as_str().unwrap().to_owned();
                publish::tick(&state).await.unwrap();
                let target = get_post(&s, &cookie, &id).await["targets"][0]["id"]
                    .as_str()
                    .unwrap()
                    .parse::<uuid::Uuid>()
                    .unwrap();
                set_body(&db, &id, "fine", json!([])).await;
                let fail_with = |error: String| {
                    let db = &db;
                    async move {
                        let row = post_targets::ActiveModel {
                            id: Set(target),
                            status: Set("failed".into()),
                            error: Set(Some(error)),
                            ..Default::default()
                        };
                        post_targets::Entity::update(row).exec(db).await.unwrap();
                    }
                };
                // Each kind of failure that may already have posted.
                let kinds = [
                    "Timed out; it may have posted, check the account.",
                    "Thread post 2 of 3: Timed out; it may have posted, check the account. The posts before it are up.",
                    "Unknown, check the account: publishing stopped midway and it may have posted.",
                    "Unknown, check the account: publishing stopped midway and thread post 2 of 3 may have posted.",
                    "Thread post 2 of 3 went out but could not be saved: it may be live, check the account.",
                    "TikTok has not said it is done and may still post it. Check the account before posting again.",
                    "Upload: YouTube sent no video id. It may have posted, check the channel.",
                ];
                let before = RECORDS.lock().unwrap().len();
                for kind in kinds {
                    fail_with(kind.to_owned()).await;
                    let res = req(&s, Method::POST, &retry_url(&id), &cookie).await;
                    assert_eq!(res.status_code(), 409, "{kind}: {}", res.text());
                    let body = res.json::<Value>();
                    assert_eq!(body["error"], "outcome_unknown", "{kind}");
                    assert_eq!(body["targets"][0]["target_id"], target.to_string());
                    assert_eq!(body["targets"][0]["error"], kind);
                }
                // A target cut off for real: recovery fails it, and the retry still refuses.
                let cut = post_targets::ActiveModel {
                    id: Set(target),
                    status: Set("publishing".into()),
                    error: Set(None),
                    updated_at: Set(
                        (Utc::now() - Duration::minutes(publish::STUCK_MINUTES + 5)).fixed_offset()
                    ),
                    ..Default::default()
                };
                post_targets::Entity::update(cut).exec(&db).await.unwrap();
                publish::recover_stuck(&db).await.unwrap();
                let url = format!("/v1/post-groups/{gid}/retry");
                let res = req(&s, Method::POST, &url, &cookie).await;
                assert_eq!(res.status_code(), 409, "{}", res.text());
                assert_eq!(res.json::<Value>()["error"], "outcome_unknown");
                assert_eq!(RECORDS.lock().unwrap().len(), before, "nothing was sent");

                // Next to a plain failure, the retry goes on and lists what it left alone.
                let plain = uuid::Uuid::now_v7();
                let row = post_targets::ActiveModel {
                    id: Set(plain),
                    post_id: Set(id.parse().unwrap()),
                    social_account_id: Set(None),
                    status: Set("failed".into()),
                    error: Set(Some("Bluesky refused it (InvalidRequest).".into())),
                    ..Default::default()
                };
                post_targets::Entity::insert(row)
                    .exec_without_returning(&db)
                    .await
                    .unwrap();
                let res = req(
                    &s,
                    Method::POST,
                    &format!("/v1/post-groups/{gid}/retry"),
                    &cookie,
                )
                .await;
                assert_eq!(res.status_code(), 202, "{}", res.text());
                let body = res.json::<Value>();
                let skipped = body["skipped_targets"].as_array().unwrap();
                assert_eq!(skipped.len(), 1);
                assert_eq!(skipped[0]["target_id"], target.to_string());
                assert_eq!(skipped[0]["reason"], "outcome_unknown");
                settled(&s, &cookie, &id).await;
                let row = post_targets::Entity::find_by_id(target)
                    .one(&db)
                    .await
                    .unwrap()
                    .unwrap();
                assert_eq!(row.status, "failed", "the unsure target stays as it was");
                assert_eq!(RECORDS.lock().unwrap().len(), before, "and was not sent");
            }

